 page.locator('[data-ob19-photo-file]').set_input_files({'name':'bad.txt','mimeType':'text/plain','buffer':b'not a photo'});page.locator('[data-ob19-photo-save]').click();page.get_by_text('JPEG・PNG・WebP・GIFの画像（20MBまで）を選んでください。',exact=True).wait_for();assert page.evaluate('async()=> (await OUTBASE_REPOSITORIES_V160.media.all()).length')==0;page.locator('[data-ob19-photo-cancel]').click();print('Unsupported file rejected without writes: PASS',flush=True)
 page.locator('[data-ob19-photo-file]').set_input_files(file);page.locator('[data-ob19-photo-editor]').wait_for()
