 page.locator('[data-ob19-photo-save]').click();page.get_by_text('写真を保存できませんでした。選択した写真は残っています。もう一度お試しください。',exact=True).wait_for()
 counts=page.evaluate('async()=>({records:(await OUTBASE_REPOSITORIES_V160.records.all()).length,media:(await OUTBASE_REPOSITORIES_V160.media.all()).length})');assert counts=={'records':0,'media':0};assert 'test-photo.png' in page.locator('[data-ob19-photo-editor]').inner_text();print('Mid-transaction failure rolls back record and Blob; selection retained: PASS',flush=True)
 page.evaluate('()=>{IDBObjectStore.prototype.put=window.originalPhotoPut}');c.set_offline(True)
 page.locator('[data-ob19-photo-save]').evaluate('(button)=>{button.click();button.click()}')
 page.locator('[data-ob19-photo-key]').wait_for();page.wait_for_function('document.querySelector("[data-ob19-photo-key]")?.naturalWidth===48');print('Offline save and image display: PASS',flush=True)
 saved=page.evaluate('async()=>{const media=(await OUTBASE_REPOSITORIES_V160.media.all())[0];const bytes=new Uint8Array(await media.blob.arrayBuffer());return {records:(await OUTBASE_REPOSITORIES_V160.records.all()).length,mediaCount:(await OUTBASE_REPOSITORIES_V160.media.all()).length,activityId:media.activity_id,name:media.filename,size:media.size,bytes:btoa(String.fromCharCode(...bytes)),key:OUTBASE_PHOTO_RECORDS.keyFor(media)}}');assert saved['records']==1 and saved['mediaCount']==1;assert saved['activityId']==aid and saved['name']==file['name'] and saved['bytes']==PNG;print('Original bytes, filename and activity relation preserved; one record only: PASS',flush=True)
 dedup=page.evaluate('async()=>{const media=(await OUTBASE_REPOSITORIES_V160.media.all())[0];return (await OUTBASE_PHOTO_RECORDS.save({activityId:media.activity_id,displayActivityId:media.activity_id,file:media.blob,requestId:media.id})).deduplicated}');assert dedup;print('Retry is idempotent: PASS',flush=True)
 backup=page.evaluate('async()=>{const result=await OUTBASE_STORAGE_EXPORT_V1.createArchive({includeCacheStorage:false,databaseNames:["outbase_story_db"]});const check=await OUTBASE_ISOLATED_ARCHIVE_VERIFIER_V1.verify(result.archive,{explicit:true});const media=result.archive.indexedDB.find(db=>db.name==="outbase_story_db").stores.find(store=>store.name==="media").rows[0].value;return {blob:media.blob,verified:check.ok,sourceUnchanged:!check.currentDatabasesModified}}');assert backup['verified'] and backup['sourceUnchanged'];assert backup['blob']['data']==PNG;print('Non-destructive backup preserves original photo and passes isolated verification: PASS',flush=True)
 c.set_offline(False);page.reload();page.locator('[data-ob19-photo-key]').wait_for();page.wait_for_function('document.querySelector("[data-ob19-photo-key]")?.naturalWidth===48');print('Photo restored after reload: PASS',flush=True)
 page.evaluate('()=>{window.photoShellModel=OUTBASE_SHELL_MODEL_V166;OUTBASE_SHELL_MODEL_V166={...OUTBASE_SHELL_MODEL_V166,preload:async()=>{throw Error("test refresh failure")}}}')
 page.locator('[data-ob19-photo-file]').set_input_files({**file,'name':'second-photo.png'});page.locator('[data-ob19-photo-save]').click();page.get_by_text('写真は保存済みですが、表示を更新できませんでした。実行画面を開き直してください。',exact=True).wait_for();assert page.evaluate('async()=> (await OUTBASE_REPOSITORIES_V160.media.all()).length')==2;print('Readback failure does not misreport a committed photo as unsaved: PASS',flush=True)
 page.evaluate('()=>{OUTBASE_SHELL_MODEL_V166=window.photoShellModel}');page.reload();page.wait_for_function('document.querySelectorAll("[data-ob19-photo-key]").length===2');page.wait_for_function('[...document.querySelectorAll("[data-ob19-photo-key]")].every(image=>image.naturalWidth===48)');print('Both committed photos restored after reopening: PASS',flush=True)
 page.locator('[data-ob19-detail]').click();page.wait_for_url('**view=activity**');page.wait_for_function('[...document.querySelectorAll("[data-ob-media-key]")].some(node=>node.classList.contains("has-photo"))');print('Activity cover resolves Story photo without legacy writes: PASS',flush=True)
 assert not errors,errors;print('JavaScript errors: NONE',flush=True);c.close();b.close()
